<script>
const canvas = document.getElementById('gameCanvas');
const ctx    = canvas.getContext('2d');

const W = 375, H = 667;
const dpr = Math.min(window.devicePixelRatio || 1, 2);
canvas.width  = W * dpr;
canvas.height = H * dpr;
canvas.style.width  = W + 'px';
canvas.style.height = H + 'px';
ctx.scale(dpr, dpr);

const BLK_COLORS = [
  '#e94560','#0f3460','#16213e','#533483',
  '#f5a623','#4ecca3','#aaaaaa','#00b4d8','#ff6b6b','#a29bfe'
];

let score   = 0;
let best    = parseInt(localStorage.getItem('jjBest') || '0');
let running = false;
let dead    = false;

const PW = 28, PH = 36;
let px, py, pvy, pvx;
let jumpCount = 0;

const BX = 20;
const BW_MAX = 80, BW_MIN = 45;
const GAP_MIN = 70, GAP_MAX = 170;
let blocks = [];
let curX, curY, curW;
let camY = 0;

function newBlock() {
  const w   = BW_MIN + Math.random() * (BW_MAX - BW_MIN);
  const h   = 18 + Math.random() * 10;
  const gap = GAP_MIN + Math.random() * (GAP_MAX - GAP_MIN);
  const nx  = BX + Math.random() * (W - BX * 2 - w);
  const last = blocks[blocks.length - 1];
  const ny  = (last ? last.y : H - 100) - gap - h;
  const color = BLK_COLORS[Math.floor(Math.random() * BLK_COLORS.length)];
  return { x: nx, y: ny, w, h, color, landed: 0, shine: 0 };
}

function initBlocks() {
  blocks = [];
  curW = 90; curX = (W - curW) / 2; curY = H - 120;
  const sc = BLK_COLORS[Math.floor(Math.random() * BLK_COLORS.length)];
  blocks.push({ x: curX, y: curY, w: curW, h: 22, color: sc, landed: 1, shine: 0.3 });
  for (let i = 0; i < 7; i++) blocks.push(newBlock());
}

function resetPlayer() {
  px = curX + curW / 2 - PW / 2;
  py = curY - PH;
  pvy = 0; pvx = 0;
}

let charging = false, chargeT = 0;
const CHARGE_RATE = 1.6;
let jumpActive = false;
let targetX = 0, targetY = 0;

function startCharge() { if (!running) return; charging = true; chargeT = 0; }
function releaseCharge() {
  if (!charging || !running) return;
  charging = false;
  const power = Math.min(chargeT / CHARGE_RATE, 1);
  chargeT = 0;
  const dx = targetX - (px + PW / 2);
  const dy = targetY - (py + PH / 2);
  const dist = Math.sqrt(dx * dx + dy * dy);
  const speed = 350 + power * 750;
  const ratio = speed / Math.max(dist, 1);
  pvx = dx * ratio; pvy = dy * ratio;
  jumpActive = true;
}

const stars = Array.from({ length: 90 }, () => ({
  x: Math.random() * W, y: Math.random() * H,
  r: Math.random() * 1.5 + 0.3,
  a: Math.random(), da: (Math.random() - 0.5) * 0.015,
}));

let particles = [];
function burst(x, y, color, n) {
  for (let i = 0; i < n; i++) {
    const a = Math.random() * Math.PI * 2;
    const spd = 40 + Math.random() * 120;
    particles.push({
      x, y,
      vx: Math.cos(a) * spd, vy: Math.sin(a) * spd,
      life: 1, decay: 0.03 + Math.random() * 0.04,
      r: 2 + Math.random() * 3, color,
    });
  }
}

const trail = [];
const MAX_TRAIL = 14;

function drawChar(x, y) {
  const cx = x + PW / 2;
  const headY = y + 7;
  const bodyT = headY + 9;
  const bodyB = y + PH * 0.65;
  const lw = jumpActive ? Math.sin(jumpCount * 0.6) * 6 : 0;
  const aw = jumpActive ? Math.sin(jumpCount * 0.6) * 4 : 0;

  ctx.beginPath();
  ctx.ellipse(cx, y + PH, PW * 0.45, 4, 0, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(0,0,0,0.25)'; ctx.fill();

  ctx.strokeStyle = '#fff'; ctx.lineWidth = 2.5; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(cx, bodyT); ctx.lineTo(cx, bodyB); ctx.stroke();
  ctx.beginPath(); ctx.arc(cx, headY, 7, 0, Math.PI * 2);
  ctx.fillStyle = '#fff'; ctx.fill();
  ctx.beginPath();
  ctx.moveTo(cx, bodyT + 4); ctx.lineTo(cx - 10, bodyT + 12 + aw);
  ctx.moveTo(cx, bodyT + 4); ctx.lineTo(cx + 10, bodyT + 12 - aw);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(cx, bodyB); ctx.lineTo(cx - 5, y + PH - 1 + lw);
  ctx.moveTo(cx, bodyB); ctx.lineTo(cx + 5, y + PH - 1 - lw);
  ctx.stroke();
}

function drawBlock(b, sy) {
  ctx.save();
  if (b.shine > 0.01) { ctx.shadowColor = b.color; ctx.shadowBlur = 20 * b.shine; }
  ctx.beginPath(); ctx.roundRect(b.x, sy, b.w, b.h, 5);
  ctx.fillStyle = b.color; ctx.fill();
  ctx.shadowBlur = 0;
  ctx.beginPath(); ctx.roundRect(b.x + 2, sy + 2, b.w - 4, 4, 3);
  ctx.fillStyle = 'rgba(255,255,255,0.22)'; ctx.fill();
  ctx.beginPath(); ctx.roundRect(b.x, sy, 4, b.h, [5, 0, 0, 5]);
  ctx.fillStyle = 'rgba(0,0,0,0.2)'; ctx.fill();
  if (b.shine > 0.01) {
    const r = (1 - b.shine) * b.w * 0.7;
    ctx.beginPath(); ctx.arc(b.x + b.w / 2, sy + b.h / 2, r, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(255,255,255,${b.shine * 0.5})`; ctx.lineWidth = 2; ctx.stroke();
  }
  ctx.restore();
}

function drawPowerBar() {
  if (!charging) return;
  const power = Math.min(chargeT / CHARGE_RATE, 1);
  const bw = 120, bh = 10, bx = W / 2 - bw / 2, by = H - 80;
  ctx.save();
  ctx.fillStyle = 'rgba(255,255,255,0.1)';
  ctx.beginPath(); ctx.roundRect(bx, by, bw, bh, 5); ctx.fill();
  const grad = ctx.createLinearGradient(bx, 0, bx + bw, 0);
  grad.addColorStop(0,   '#4ecca3');
  grad.addColorStop(0.5, '#f5a623');
  grad.addColorStop(1,   '#e94560');
  ctx.fillStyle = grad;
  ctx.beginPath(); ctx.roundRect(bx, by, bw * power, bh, 5); ctx.fill();
  ctx.shadowColor = power > 0.7 ? '#e94560' : '#4ecca3';
  ctx.shadowBlur  = 10 * power; ctx.fill();
  ctx.restore();
}

function update(dt) {
  if (!running) return;
  if (charging) chargeT += dt;

  if (jumpActive) {
    jumpCount++;
    px += pvx * dt; py += pvy * dt; pvy += 1400 * dt;
    trail.push({ x: px + PW / 2, y: py + PH / 2 });
    if (trail.length > MAX_TRAIL) trail.shift();

    let landed = false;
    for (const b of blocks) {
      if (px + PW > b.x && px < b.x + b.w &&
          py + PH >= b.y && py + PH <= b.y + b.h + 20) {
        if (!b.landed) {
          score++; b.landed = 1; b.shine = 1;
          burst(px + PW / 2, b.y, b.color, 14);
          updateScoreUI(); prepareNextTarget();
        }
        py = b.y - PH; pvy = 0; pvx = 0;
        jumpActive = false; landed = true; break;
      }
    }
    if (py > camY + H + 200) triggerDeath();
  }

  const targetCam = py - H * 0.55;
  if (targetCam < camY) camY += (targetCam - camY) * 0.1;

  for (const b of blocks) { if (b.shine > 0) b.shine = Math.max(0, b.shine - dt * 2.5); }
  for (const p of particles) {
    p.x += p.vx * dt; p.y += p.vy * dt; p.vy += 300 * dt; p.life -= p.decay;
  }
  particles = particles.filter(p => p.life > 0);
  for (const s of stars) {
    s.a += s.da;
    if (s.a < 0 || s.a > 1) s.da *= -1;
  }
}

function render() {
  ctx.clearRect(0, 0, W, H);
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0,   '#0d0d1f');
  sky.addColorStop(0.6, '#1a1a2e');
  sky.addColorStop(1,   '#16213e');
  ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);

  for (const s of stars) {
    ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255,255,255,${0.2 + s.a * 0.6})`; ctx.fill();
  }

  for (const b of blocks) {
    const sy = b.y - camY;
    if (sy > -60 && sy < H + 60) drawBlock(b, sy);
  }

  for (let i = 0; i < trail.length; i++) {
    const t = trail[i];
    ctx.beginPath();
    ctx.arc(t.x, t.y - camY, (i / trail.length) * 4 + 1, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255,255,255,${(i / trail.length) * 0.4})`; ctx.fill();
  }

  if (running && !dead) drawChar(px, py - camY);

  for (const p of particles) {
    ctx.beginPath();
    ctx.arc(p.x, p.y - camY, p.r * p.life, 0, Math.PI * 2);
    const alpha = Math.floor(p.life * 200).toString(16).padStart(2, '0');
    ctx.fillStyle = p.color + alpha; ctx.fill();
  }

  drawPowerBar();

  if (running && !dead) {
    ctx.save();
    ctx.beginPath(); ctx.arc(targetX, targetY - camY, 5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.3)'; ctx.fill();
    ctx.restore();
  }
}

function updateScoreUI() {
  document.getElementById('scoreVal').textContent = score;
  if (score > best) { best = score; localStorage.setItem('jjBest', best); }
  document.getElementById('bestVal').textContent = '最高 ' + best;
}

function prepareNextTarget() {
  const next = blocks[score];
  if (next) { targetX = next.x + next.w / 2; targetY = next.y + next.h / 2; }
}

function triggerDeath() {
  if (dead) return;
  dead = true; running = false;
  burst(px + PW / 2, py - camY, '#e94560', 30);
  burst(px + PW / 2, py - camY, '#fff', 15);
  setTimeout(() => {
    document.getElementById('goScore').textContent = score;
    document.getElementById('goBest').textContent  = '最高 ' + best;
    document.getElementById('gameOverPanel').style.display = 'flex';
    document.getElementById('hint').style.display = 'none';
  }, 600);
}

function startGame() {
  score = 0; dead = false; charging = false; chargeT = 0;
  jumpActive = false; jumpCount = 0;
  trail.length = 0; particles = []; camY = 0;
  document.getElementById('gameOverPanel').style.display = 'none';
  document.getElementById('hint').style.display = 'block';
  initBlocks(); resetPlayer(); prepareNextTarget(); updateScoreUI();
  running = true;
}

canvas.addEventListener('mousedown',  e => { e.preventDefault(); startCharge(); });
canvas.addEventListener('mouseup',    e => { e.preventDefault(); releaseCharge(); });
canvas.addEventListener('mouseleave', ()  => { if (charging) releaseCharge(); });
canvas.addEventListener('touchstart', e => { e.preventDefault(); startCharge(); }, { passive: false });
canvas.addEventListener('touchend',   e => { e.preventDefault(); releaseCharge(); }, { passive: false });
canvas.addEventListener('touchcancel',()  => { if (charging) releaseCharge(); });
document.getElementById('restartBtn').addEventListener('click', startGame);

document.getElementById('bestVal').textContent = '最高 ' + best;
startGame();

let lastTs = 0;
function loop(ts) {
  const dt = Math.min((ts - lastTs) / 1000, 0.05);
  lastTs = ts;
  update(dt); render();
  requestAnimationFrame(loop);
}
requestAnimationFrame(ts => { lastTs = ts; requestAnimationFrame(loop); });
</script>
</body>
</html>
ENDOFFILE

